<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { api, currency, formatDate } from '../services/api'
import type { Category, Order, PageResult, Product } from '../types'
interface Dashboard { user_count:number;active_product_count:number;order_count:number;pending_order_count:number;paid_revenue:number;low_stock_variant_count:number;latest_orders:Order[] }
const dashboard=ref<Dashboard|null>(null);const categories=ref<Category[]>([]);const products=ref<Product[]>([]);const orders=ref<Order[]>([]);const loading=ref(true);const busy=ref(false);const error=ref('');const message=ref('');const activeTab=ref<'overview'|'products'|'orders'|'inventory'>('overview')
const productForm=reactive({category_id:'',name:'',slug:'',description:'',image_url:'https://placehold.co/800x600/e6efea/137c70?text=NusaMart',sku:'',price:99000,stock_quantity:10,attributes:'{"Warna":"Default"}'})
const categoryForm=reactive({name:'',slug:'',description:''})
const stockForm=reactive({variant_id:'',delta:1,note:'Penyesuaian stok admin'})
const ordersFilter=ref('')
function setTab(tab: 'overview'|'products'|'orders'|'inventory'){activeTab.value=tab}
async function load(){loading.value=true;error.value='';try{const [d,c,p,o]=await Promise.all([api.get<Dashboard>('/api/v1/admin/dashboard'),api.get<Category[]>('/api/v1/categories'),api.get<PageResult<Product>>('/api/v1/admin/products?page=1&page_size=100'),api.get<PageResult<Order>>('/api/v1/admin/orders?page=1&page_size=100')]);dashboard.value=d;categories.value=c;products.value=p.items;orders.value=o.items;if(!productForm.category_id&&c.length)productForm.category_id=c[0].id;if(!stockForm.variant_id&&p.items[0]?.variants[0])stockForm.variant_id=p.items[0].variants[0].id}catch(e){error.value=e instanceof Error?e.message:'Gagal memuat dashboard'}finally{loading.value=false}}
function slugify(value:string){return value.toLowerCase().trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
async function createCategory(){busy.value=true;error.value='';message.value='';try{await api.post('/api/v1/admin/categories',{...categoryForm,slug:categoryForm.slug||slugify(categoryForm.name)});Object.assign(categoryForm,{name:'',slug:'',description:''});message.value='Kategori dibuat';await load()}catch(e){error.value=e instanceof Error?e.message:'Gagal membuat kategori'}finally{busy.value=false}}
async function createProduct(){busy.value=true;error.value='';message.value='';try{let attrs:Record<string,string>;try{attrs=JSON.parse(productForm.attributes)}catch{throw new Error('Atribut varian harus berupa JSON valid')}await api.post('/api/v1/admin/products',{category_id:productForm.category_id,name:productForm.name,slug:slugify(productForm.slug||productForm.name),description:productForm.description,image_url:productForm.image_url,status:'active',variants:[{sku:productForm.sku,attributes:attrs,price:productForm.price,stock_quantity:productForm.stock_quantity}]});Object.assign(productForm,{name:'',slug:'',description:'',sku:'',price:99000,stock_quantity:10,attributes:'{"Warna":"Default"}'});message.value='Produk berhasil dibuat';await load()}catch(e){error.value=e instanceof Error?e.message:'Gagal membuat produk'}finally{busy.value=false}}
async function archive(p:Product){if(!confirm(`Arsipkan produk “${p.name}”?`))return;try{await api.delete('/api/v1/admin/products/'+p.id);message.value='Produk diarsipkan';await load()}catch(e){error.value=e instanceof Error?e.message:'Gagal mengarsipkan produk'}}
async function adjustStock(){busy.value=true;error.value='';message.value='';try{const result=await api.post<{stock_available:number}>('/api/v1/admin/inventory/adjust',stockForm);message.value=`Stok berhasil diperbarui. Tersedia: ${result.stock_available}`;await load()}catch(e){error.value=e instanceof Error?e.message:'Gagal menyesuaikan stok'}finally{busy.value=false}}
async function setOrderStatus(order:Order,status:'shipped'|'delivered'|'cancelled'){const tracking=status==='shipped'?prompt('Masukkan nomor resi (opsional):')??undefined:undefined;busy.value=true;error.value='';try{await api.patch(`/api/v1/admin/orders/${order.id}/status`,{status,tracking_number:tracking||null});message.value=`Status ${order.order_number} diperbarui`;await load()}catch(e){error.value=e instanceof Error?e.message:'Gagal memperbarui status pesanan'}finally{busy.value=false}}
onMounted(load)
const filteredOrders=()=>ordersFilter.value?orders.value.filter(o=>o.status===ordersFilter.value):orders.value
</script>
<template><section class="page-intro admin-intro"><div><p class="eyebrow">NUSAMART MANAGEMENT</p><h1>Dashboard admin</h1><p>Kelola katalog, stok, dan pemenuhan pesanan dari satu tempat.</p></div><button class="button-secondary" @click="load">↻ Refresh data</button></section><p v-if="error" class="error-banner">{{ error }}</p><p v-if="message" class="success-banner">{{ message }}</p><div v-if="loading" class="loading-state"><span class="spinner"></span>Memuat dashboard…</div><template v-else><div class="admin-tabs"><button v-for="tab in [{id:'overview',label:'Ringkasan'},{id:'products',label:'Produk & kategori'},{id:'inventory',label:'Inventori'},{id:'orders',label:'Pesanan'}]" :key="tab.id" :class="{active:activeTab===tab.id}" @click="setTab(tab.id as 'overview'|'products'|'orders'|'inventory')">{{ tab.label }}</button></div><template v-if="activeTab==='overview'"><div class="metric-grid"><article class="metric-card"><span>Pengguna</span><strong>{{ dashboard?.user_count??0 }}</strong><small>akun terdaftar</small></article><article class="metric-card"><span>Produk aktif</span><strong>{{ dashboard?.active_product_count??0 }}</strong><small>produk di katalog</small></article><article class="metric-card"><span>Semua pesanan</span><strong>{{ dashboard?.order_count??0 }}</strong><small>{{ dashboard?.pending_order_count??0 }} menunggu pembayaran</small></article><article class="metric-card"><span>Pendapatan terbayar</span><strong>{{ currency(dashboard?.paid_revenue??0) }}</strong><small>{{ dashboard?.low_stock_variant_count??0 }} varian stok rendah</small></article></div><section class="panel admin-table-panel"><div class="section-heading"><div><p class="eyebrow">AKTIVITAS</p><h2>Pesanan terbaru</h2></div><button class="text-link button-as-link" @click="activeTab='orders'">Kelola pesanan →</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Order</th><th>Tanggal</th><th>Status</th><th>Total</th></tr></thead><tbody><tr v-for="o in dashboard?.latest_orders??[]" :key="o.id"><td><strong>{{ o.order_number }}</strong></td><td>{{ formatDate(o.created_at) }}</td><td><span class="status-pill" :class="'status-'+o.status">{{ o.status }}</span></td><td>{{ currency(o.total) }}</td></tr><tr v-if="!dashboard?.latest_orders.length"><td colspan="4" class="muted">Belum ada transaksi.</td></tr></tbody></table></div></section></template><template v-else-if="activeTab==='products'"><div class="admin-work-grid"><section class="panel"><p class="eyebrow">KATALOG</p><h2>Tambah produk</h2><form class="form-stack" @submit.prevent="createProduct"><label class="field-label">Kategori<select v-model="productForm.category_id" required><option v-for="c in categories" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label class="field-label">Nama produk<input v-model="productForm.name" required minlength="2" maxlength="180" @blur="!productForm.slug&&(productForm.slug=slugify(productForm.name))"/></label><label class="field-label">Slug<input v-model="productForm.slug" placeholder="otomatis-dari-nama"/></label><label class="field-label">Deskripsi<textarea v-model="productForm.description" required minlength="5" rows="3"/></label><label class="field-label">URL gambar<input v-model="productForm.image_url" required/></label><div class="form-grid"><label class="field-label">SKU<input v-model="productForm.sku" required placeholder="SKU-UNIK"/></label><label class="field-label">Harga (IDR)<input v-model.number="productForm.price" type="number" required min="0"/></label><label class="field-label">Stok awal<input v-model.number="productForm.stock_quantity" type="number" required min="0"/></label></div><label class="field-label">Atribut varian (JSON)<input v-model="productForm.attributes" required/><small class="muted">Contoh: {"Warna":"Hitam"}</small></label><button class="button-primary" :disabled="busy||!categories.length">{{ busy?'Menyimpan…':'Buat produk' }}</button></form></section><section class="panel"><p class="eyebrow">KATEGORI</p><h2>Tambah kategori</h2><form class="form-stack" @submit.prevent="createCategory"><label class="field-label">Nama kategori<input v-model="categoryForm.name" required minlength="2"/></label><label class="field-label">Slug<input v-model="categoryForm.slug" placeholder="otomatis-dari-nama"/></label><label class="field-label">Deskripsi<textarea v-model="categoryForm.description" rows="3"/></label><button class="button-secondary" :disabled="busy">Buat kategori</button></form><div class="category-admin-list"><div v-for="c in categories" :key="c.id"><span>{{ c.name }}</span><code>{{ c.slug }}</code></div></div></section></div><section class="panel admin-table-panel"><div class="section-heading"><div><p class="eyebrow">KATALOG</p><h2>Daftar produk</h2></div><span class="muted">{{ products.length }} produk</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Produk</th><th>Kategori</th><th>Harga mulai</th><th>Varian</th><th>Stok tersedia</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="p in products" :key="p.id"><td><div class="table-product"><img :src="p.image_url" :alt="p.name"/><strong>{{ p.name }}</strong></div></td><td>{{ p.category_name }}</td><td>{{ currency(p.min_price) }}</td><td>{{ p.variants.length }}</td><td>{{ p.variants.reduce((s,v)=>s+v.stock_available,0) }}</td><td>{{ p.status }}</td><td><button class="link-button danger-text" v-if="p.status!=='archived'" @click="archive(p)">Arsipkan</button></td></tr></tbody></table></div></section></template><template v-else-if="activeTab==='inventory'"><section class="panel inventory-adjust"><p class="eyebrow">STOCK CONTROL</p><h2>Penyesuaian stok</h2><form class="form-grid" @submit.prevent="adjustStock"><label class="field-label span-two">Varian SKU<select v-model="stockForm.variant_id" required><template v-for="p in products" :key="p.id"><option v-for="v in p.variants" :key="v.id" :value="v.id">{{ p.name }} — {{ v.sku }} (tersedia {{ v.stock_available }})</option></template></select></label><label class="field-label">Perubahan stok<input v-model.number="stockForm.delta" type="number" required min="-100000" max="100000"/></label><label class="field-label">Catatan<input v-model="stockForm.note" required minlength="3"/></label><div class="span-two"><button class="button-primary" :disabled="busy||!stockForm.variant_id">Simpan penyesuaian</button></div></form></section><section class="panel admin-table-panel"><h2>Status inventori</h2><div class="table-scroll"><table class="data-table"><thead><tr><th>Produk</th><th>SKU</th><th>Varian</th><th>Stok fisik</th><th>Reservasi</th><th>Tersedia</th></tr></thead><tbody><template v-for="p in products" :key="p.id"><tr v-for="v in p.variants" :key="v.id"><td>{{ p.name }}</td><td>{{ v.sku }}</td><td>{{ Object.values(v.attributes).join(' / ')||'Default' }}</td><td>{{ v.stock_quantity }}</td><td>{{ v.stock_quantity-v.stock_available }}</td><td><span :class="v.stock_available<=5?'danger-text':'success-text'">{{ v.stock_available }}</span></td></tr></template></tbody></table></div></section></template><template v-else><section class="panel admin-table-panel"><div class="section-heading"><div><p class="eyebrow">FULFILLMENT</p><h2>Kelola pesanan</h2></div><label class="field-label inline-filter">Filter status<select v-model="ordersFilter"><option value="">Semua status</option><option value="pending_payment">Menunggu pembayaran</option><option value="processing">Diproses</option><option value="shipped">Dikirim</option><option value="delivered">Selesai</option><option value="cancelled">Dibatalkan</option></select></label></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Order</th><th>Penerima</th><th>Tanggal</th><th>Item</th><th>Status</th><th>Total</th><th>Aksi</th></tr></thead><tbody><tr v-for="o in orders.filter(x=>!ordersFilter||x.status===ordersFilter)" :key="o.id"><td><strong>{{ o.order_number }}</strong></td><td>{{ o.shipping_address.recipient_name }}<small class="table-subtext">{{ o.shipping_address.city }}</small></td><td>{{ formatDate(o.created_at) }}</td><td>{{ o.items.reduce((s,x)=>s+x.quantity,0) }}</td><td><span class="status-pill" :class="'status-'+o.status">{{ o.status }}</span><small class="table-subtext">Pembayaran: {{ o.payment_status }}</small></td><td>{{ currency(o.total) }}</td><td><div class="table-actions"><button v-if="o.status==='processing'" class="button-mini" @click="setOrderStatus(o,'shipped')">Kirim</button><button v-if="o.status==='shipped'" class="button-mini" @click="setOrderStatus(o,'delivered')">Selesai</button><span v-if="!['processing','shipped'].includes(o.status)" class="muted">—</span></div></td></tr><tr v-if="!orders.filter(x=>!ordersFilter||x.status===ordersFilter).length"><td colspan="7" class="muted">Tidak ada pesanan pada filter ini.</td></tr></tbody></table></div></section></template></template></template>
